pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract and the caller
        vm.deal(address(this), 1 ether);
        // Call lockInGuess with any bytes32 value
        bytes32 hash = keccak256("test");
        c.lockInGuess{value: 1 ether}(hash);
        // Now try to settle in the same block – reference would have stored block.number+1
        // so block.number > guess.block is false for reference? Wait: reference sets block.number+1, so in same block block.number > block.number+1 is false, so settle reverts for both? Actually we need to differentiate. Let me re-evaluate.
        // For reference: guesses[msg.sender].block = block.number + 1, so settle requires block.number > block.number+1 which is false, so settle reverts.
        // For bug: guesses[msg.sender].block = block.number, so settle requires block.number > block.number which is false, also reverts. So no difference in same block.
        // Both revert. Need to test after one block: reference passes, bug reverts.
        // Let's warp one block ahead.
        vm.roll(block.number + 1);
        // Now reference: block.number > (block.number+1) is false? Wait original block.number + 1 = old block.number + 1, now block.number = old + 1, so block.number > old + 1 is false. Actually after one block, old block.number = N, reference stored N+1. Now block.number = N+1, condition block.number > N+1 is false. So still reverts. Need two blocks ahead.
        vm.roll(block.number + 1);
        // Now block.number = N+2, reference stored N+1, condition holds. Bug stored N, condition fails.
        // So call settle:
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        // Reference should succeed, bug should revert -> ok = false for bug
        assertTrue(ok, "Reference should settle successfully");
    }
}

