pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the test contract to send ether to C for deployment and lockInGuess
        vm.deal(address(this), 3 ether);
        // Deploy C with 1 ether
        address(c).call{value: 1 ether}("");

        // Alice locks in a guess
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(blockhash(block.number))));

        // Move to next block
        vm.warp(block.timestamp + 1);
        vm.roll(block.number + 1);

        // Alice attempts to settle
        bool ok;
        vm.prank(alice);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: settle succeeds and sends 2 ether; bug: settle reverts (block.number == guesses[alice].block)
        assertTrue(ok == true, "settle should succeed on reference");
    }
}

