pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(address(this), 2 ether);
        vm.deal(alice, 1 ether);

        // Alice locks in with any hash; we'll compute the expected block hash later
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(bytes32(uint256(0xdeadbeef)));

        // Warp to the next block after lockInGuess
        // lockInGuess sets guesses[alice].block = block.number + 1
        // So we need to advance to at least block.number + 2 to settle
        vm.roll(block.number + 3);

        // Alice settles; reference would succeed if guess equals blockhash, else fail
        // But the bug always stores bytes32(0), so it will never match a non-zero blockhash
        // We need the guess to match; since we control the blockhash, we can set it
        // However vm.roll doesn't change blockhash; we use vm.warp to change block number
        // Actually blockhash returns 0 for all but last 256 blocks in foundry; we need a non-zero hash
        // We'll warp to a block where blockhash is predictable or use block.number after roll
        vm.warp(block.timestamp + 1); // advance timestamp as well

        // Now the blockhash for the target block (which was block.number+1 at lock time) is 0 in foundry
        // So the reference will not match either; we need a different approach
        // Let's make Alice's guess equal to bytes32(0) and then the reference will match (since blockhash is 0)
        // Reset: create fresh contract
        c = new C();
        vm.deal(address(this), 2 ether);
        vm.deal(alice, 1 ether);

        // Alice locks in with bytes32(0) as guess
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(bytes32(0));

        // Advance to block after the stored block
        uint256 targetBlock = block.number; // lockInGuess sets block.number+1, so target = current+1
        vm.roll(targetBlock + 2);

        // Alice settles; reference will succeed because guess == bytes32(0) == blockhash(targetBlock)
        vm.prank(alice);
        c.settle();

        // Check that Alice received the 2 ETH
        assertTrue(alice.balance == 3 ether);
    }
}

