pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether (already in constructor)
        // Fund Alice with 2 ether
        address alice = address(0xBEEF);
        vm.deal(alice, 2 ether);

        // Alice locks in a guess with some hash while we can force next block hash to be 0x00
        vm.warp(1);
        vm.roll(1);
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(bytes32(0xff));

        // Move to next block with hash = 0x00
        vm.roll(2);
        // blockhash(2) should be 0x00 on the EVM (if not 0x00, we need another approach)
        // Actually blockhash(2) might not be 0, but we can ensure it by using block.number when blockhash is defined
        // The simplest: blockhash(2) = 0x00 on most EVM implementations when not mined
        // Better: use blockhash(block.number - 1) in settle; we need the blockhash of block 2, but blockhash(2)=0 in test
        // However, we need to ensure the reference diverges from mutant:
        // Reference: stored guess = 0xff, computed answer = blockhash(2) = 0x00, so guess != answer -> settle reverts
        // Mutant: stored guess = 0x00, computed answer = 0x00, so guess == answer -> then requires 2 ether balance, which fails -> revert
        // So both revert, but the revert reason differs. To detect difference we need to check if transfer happened.
        // We can instead test that after settle, the contract's balance changes in one but not the other.
        // But both revert, so balance stays 1 ether.
        // Actually the reference reverts in the require(guesses[msg.sender].guess == answer) which is before transfer.
        // Mutant reverts in require(address(this).balance >= 2 ether) also before transfer.
        // So no observable difference in balance.
        // Let's try a scenario where the mutant does NOT revert but reference does? 
        // If blockhash equals 0xff, reference matches and transfers, mutant has guess=0x00 so no match and reverts.
        // So we need blockhash equal to 0xff. But we cannot control blockhash directly. We can use a block where blockhash is known?
        // In foundry test, blockhash(block.number-1) for a non-mined block is 0. So blockhash(2) = 0.
        // So to make blockhash = 0xff, we need a real block? Not possible in test without cheating.
        // Alternative: use a different approach: the mutant stores bytes32(0), so it will 'win' if blockhash=0,
        // causing transfer. Reference will lose. That is an observable difference in balance.
        // But to have blockhash=0, we can settle in block.number = 2, where blockhash(1) is 0 (since no previous block).
        // Actually blockhash(1) in foundry test is 0? Let's check: blockhash(block.number-1) for block.number=2 returns blockhash(1), which is 0x00...
        // So:
        vm.warp(2);
        vm.roll(2);
        vm.prank(alice);
        c.settle(); // This will either revert or succeed
        // Wait, we need to detect if revert occurred or not. But settle() is not payable, so cannot use try/catch outside?
        // We can call it directly and the test will revert if it reverts. That's not good.
        // We need to use try/catch:
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        // For reference: stored guess = 0xff, answer = blockhash(2) = 0 (since blockhash(2) is 0 in test), so guess != answer, settle reverts -> ok = false
        // For mutant: stored guess = 0x00, answer = 0, guess == answer -> then requires balance >= 2 ether (only 1), so reverts -> ok = false
        // Both false. No difference.
        // To fix, we need to fund contract with 2 ether before settle. But constructor only sends 1. We could send another ether via deal to contract.
        vm.deal(address(c), 2 ether); // add 1 more ether to make 2
        // Now for mutant: guess == answer and balance >= 2 -> transfer: balance decreases by 2, so bal = 0.
        // For reference: guess != answer -> revert -> balance stays 2.
        // This gives observable difference.
        // But wait: deal sets balance directly, bypassing constructor. That's fine.
        // Now we need blockhash(2) = 0 for sure. In foundry, blockhash of an unmined block is 0.
        // So let's recompute:
        // After lockInGuess, block.number = 1? Actually we rolled to 1 before lock, so lockInGuess sets block = block.number + 1 = 2.
        // Then we roll to 2 and settle. The settle uses blockhash(guesses[msg.sender].block) = blockhash(2).
        // blockhash(2) in test environment (vm.roll(2))? Actually blockhash(2) is hash of block 2. But block 2 is the current block when settling? No, we rolled to 2, so block.number = 2. blockhash(2) returns 0 because block 2 is the current block (not yet mined). 
        // So blockhash(2)=0.
        // Perfect.
        // Now:
        bool okFinal;
        try c.settle() { okFinal = true; } catch { okFinal = false; }
        // Reference: ok=false (revert because guess=0xff != 0)
        // Mutant: ok=true (transfer happens)
        // So we assert: reference should have ok=false, mutant ok=true. In test we expect reference=true? No, we want the test to pass on reference and fail on mutant.
        // So we assertTrue(condition) where condition is true for reference and false for mutant.
        // We can assert that settle did NOT revert (okFinal should be false for reference?). But we want test to fail on mutant, i.e., assertTrue should be false on mutant.
        // Let's assert that address(c).balance after settle is 2 ether (reference) vs 0 (mutant).
        uint bal = address(c).balance;
        // Reference: settle reverts, balance stays 2 ether.
        // Mutant: settle succeeds, transfers 2 ether to alice, balance becomes 0 (since we had 2 ether, send 2 -> 0).
        assertTrue(bal == 2 ether); // true for reference, false for mutant.
    }
}

